/**
 * The series each catalog holds: every field of a lab, workshop upgrade, card, ultimate weapon
 * stat, bot stat or guardian chip stat that changes with level.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    labSeries, workshopSeries, cardSeries, ultimateWeaponSeries, botSeries, guardianSeries
 * depends    src/charts/series/types, src/charts/series/walk, src/data, src/data/charts/types
 * used by    src/calculators/specs.generated, src/charts/series/lookup
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import {
  BOT_UPGRADES_DATA,
  CARD_TEMPLATES,
  LAB_CATALOG,
  botStatValueAt,
  buildGuardianDefinitions,
  getWorkshopStatDefinitions,
  uwStoneChartData,
} from '../../data'
import type { ChartSeriesPoint } from '../../data/charts/types'
import type { ChartSeriesSource } from './types'
import { pointsOfList, seriesOfLevelTable, seriesSlug } from './walk'

/** A lab's cost and duration, by level. */
export function labSeries(): ChartSeriesSource[] {
  return LAB_CATALOG.flatMap(lab => seriesOfLevelTable('lab', `lab:${seriesSlug(lab.slug)}`, lab.slug, lab.name, lab.levels))
}

/** A workshop upgrade's value, cash price and coin price, by level. */
export function workshopSeries(): ChartSeriesSource[] {
  return getWorkshopStatDefinitions().flatMap(stat =>
    seriesOfLevelTable('workshop', `workshop:${seriesSlug(stat.key)}`, stat.key, stat.label, stat.levels))
}

/**
 * A card's effect by card level, and its mastery's effect by mastery level.
 *
 * Card levels run from 1; mastery levels from 0, because unlocking a mastery grants its level-0
 * effect before any lab is run.
 */
export function cardSeries(): ChartSeriesSource[] {
  return CARD_TEMPLATES.flatMap(card => {
    const series: ChartSeriesSource[] = []
    if (card.levelValues?.length) {
      series.push({
        id: `card:${seriesSlug(card.id)}:level-values`,
        family: 'card',
        entity: card.id,
        metric: 'levelValues',
        title: `${card.name}: Effect by Card Level`,
        xLabel: 'Card Level',
        yLabel: 'Effect',
        read: () => pointsOfList(card.levelValues, 1),
      })
    }
    if (card.masteryValues?.length) {
      series.push({
        id: `card:${seriesSlug(card.id)}:mastery-values`,
        family: 'card',
        entity: card.id,
        metric: 'masteryValues',
        title: `${card.name}: Mastery Effect by Mastery Level`,
        xLabel: 'Mastery Level',
        yLabel: 'Mastery Effect',
        read: () => pointsOfList(card.masteryValues ?? [], 0),
      })
    }
    return series
  })
}

/** An ultimate weapon stat's value and stone cost, by level. */
export function ultimateWeaponSeries(): ChartSeriesSource[] {
  return Object.entries(uwStoneChartData).flatMap(([weaponKey, weapon]) =>
    (weapon.stats ?? []).flatMap(stat => seriesOfLevelTable(
      'ultimate-weapon',
      `ultimate-weapon:${seriesSlug(weaponKey)}:${seriesSlug(stat.name)}`,
      weaponKey,
      `${weapon.name} ${stat.name}`,
      stat.levels,
    )))
}

/**
 * A bot stat's value by level, for the base tier and the plus tier.
 *
 * A bot stat is a formula over its levels rather than a stored table, so the points are computed.
 * A stat with no levels to buy is not a series.
 */
export function botSeries(): ChartSeriesSource[] {
  return BOT_UPGRADES_DATA.flatMap(bot => {
    const tiers = [
      { stats: bot.stats ?? {}, segment: '', tierTitle: '' },
      { stats: bot.plus?.stats ?? {}, segment: 'plus:', tierTitle: ' Plus' },
    ]
    return tiers.flatMap(({ stats, segment, tierTitle }) =>
      Object.entries(stats).flatMap(([statName, stat]): ChartSeriesSource[] => {
        if (!stat || !((stat.maxLevel ?? 0) > 0)) return []
        return [{
          id: `bot:${seriesSlug(bot.name)}:${segment}${seriesSlug(statName)}`,
          family: 'bot',
          entity: bot.name,
          metric: statName,
          title: `${bot.label}${tierTitle}: ${statName}`,
          xLabel: 'Level',
          yLabel: statName,
          ...(stat.unit ? { unit: stat.unit } : {}),
          read: (): ChartSeriesPoint[] =>
            Array.from({ length: stat.maxLevel + 1 }, (_, level) => ({ x: level, y: botStatValueAt(stat, level) })),
        }]
      }))
  })
}

/** A guardian chip stat's value and cost, by level. */
export function guardianSeries(): ChartSeriesSource[] {
  return buildGuardianDefinitions().flatMap(guardian =>
    Object.entries(guardian.stats ?? {}).flatMap(([statName, stat]) => seriesOfLevelTable(
      'guardian',
      `guardian:${seriesSlug(guardian.key)}:${seriesSlug(statName)}`,
      guardian.key,
      `${guardian.label} ${statName}`,
      stat?.levels,
    )))
}
